import React, { useRef, useEffect, useState } from 'react';
import { FaceMesh } from '@mediapipe/face_mesh';
import './VideoCapture.css';
import { extractROIs, processRPPGSignal, calculateConfidence } from '../utils/signalProcessing';

const VideoCapture = ({ onVerificationUpdate }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const [isActive, setIsActive] = useState(false);
  const [faceMesh, setFaceMesh] = useState(null);
  const [error, setError] = useState(null);
  const [status, setStatus] = useState('Ready');
  const animationFrameRef = useRef(null);

  // Signal processing state
  const rgbBufferRef = useRef({ forehead: [], leftCheek: [], rightCheek: [] });
  const trustHistoryRef = useRef([]);
  const frameCountRef = useRef(0);
  const confidenceHistoryRef = useRef([]); // For smoothing

  // Initialize MediaPipe Face Mesh
  useEffect(() => {
    let mounted = true;

    const initFaceMesh = async () => {
      try {
        setStatus('Loading face detection...');
        console.log('🔄 Initializing MediaPipe Face Mesh...');

        const mesh = new FaceMesh({
          locateFile: (file) => {
            const url = `https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/${file}`;
            console.log('📦 Loading MediaPipe file:', file);
            return url;
          }
        });

        console.log('⚙️ Configuring Face Mesh options...');
        mesh.setOptions({
          maxNumFaces: 1,
          refineLandmarks: false,
          minDetectionConfidence: 0.5,
          minTrackingConfidence: 0.5
        });

        mesh.onResults(onFaceMeshResults);

        if (mounted) {
          setFaceMesh(mesh);
          setStatus('Ready');
          console.log('✅ Face Mesh initialized successfully');
        }
      } catch (err) {
        console.error('❌ Face mesh init error:', err);
        if (mounted) {
          setError('Failed to initialize face detection: ' + err.message);
          setStatus('Error');
        }
      }
    };

    initFaceMesh();

    return () => {
      mounted = false;
    };
  }, []);

  // Start camera
  const startCamera = async () => {
    try {
      setError(null);
      setStatus('Requesting camera access...');

      // Simple constraints first
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 640 },
          height: { ideal: 480 },
          facingMode: 'user'
        },
        audio: false
      });

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        console.log('✅ Camera stream attached to video element');

        // Wait for video to be ready
        videoRef.current.onloadedmetadata = async () => {
          console.log('✅ Video metadata loaded, dimensions:', videoRef.current.videoWidth, 'x', videoRef.current.videoHeight);
          try {
            await videoRef.current.play();
            console.log('✅ Video playing');
            setIsActive(true);
            setStatus('Camera active');

            // Wait a bit for faceMesh to be ready, then start frame loop
            setTimeout(() => {
              if (faceMesh && videoRef.current) {
                console.log('🎬 Starting frame processing loop...');
                processFrame();
              } else {
                console.log('⚠️ FaceMesh not ready yet, waiting...');
              }
            }, 500);
          } catch (playErr) {
            console.error('❌ Video play error:', playErr);
            setError('Failed to start video: ' + playErr.message);
          }
        };
      }
    } catch (err) {
      console.error('Camera access error:', err);
      let errorMsg = 'Camera access denied';

      if (err.name === 'NotAllowedError') {
        errorMsg = 'Camera permission denied. Please allow camera access and refresh.';
      } else if (err.name === 'NotFoundError') {
        errorMsg = 'No camera found. Please connect a camera.';
      } else if (err.name === 'NotReadableError') {
        errorMsg = 'Camera is already in use by another application.';
      } else {
        errorMsg = err.message || 'Failed to access camera';
      }

      setError(errorMsg);
      setStatus('Error');
    }
  };

  // Stop camera
  const stopCamera = () => {
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }

    if (videoRef.current?.srcObject) {
      const tracks = videoRef.current.srcObject.getTracks();
      tracks.forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsActive(false);
    setStatus('Stopped');

    // Reset buffers
    rgbBufferRef.current = { forehead: [], leftCheek: [], rightCheek: [] };
    trustHistoryRef.current = [];
    frameCountRef.current = 0;
  };

  // Process each frame
  const processFrame = async () => {
    if (!videoRef.current || !faceMesh) {
      console.log('⏸️ Frame loop stopped: missing video or faceMesh');
      return;
    }

    if (videoRef.current.paused || videoRef.current.ended) {
      console.log('⏸️ Frame loop stopped: video paused/ended');
      return;
    }

    try {
      if (videoRef.current.readyState >= 2) {
        await faceMesh.send({ image: videoRef.current });
      }
    } catch (err) {
      console.error('❌ Frame processing error:', err);
    }

    // Continue loop
    animationFrameRef.current = requestAnimationFrame(processFrame);
  };

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  // Handle face mesh results
  const onFaceMeshResults = (results) => {
    if (!canvasRef.current) {
      console.log('⚠️ No canvas ref in results handler');
      return;
    }

    if (!results.multiFaceLandmarks?.[0]) {
      // No face detected
      if (frameCountRef.current % 60 === 0) {
        console.log('⚠️ No face detected in frame', frameCountRef.current);
      }
      onVerificationUpdate({
        status: 'UNCERTAIN',
        confidence: 0,
        signalQuality: 0,
        heartRate: 0,
        roiConsistency: 0,
        trustHistory: trustHistoryRef.current
      });
      drawFrame(results.image);
      return;
    }

    if (frameCountRef.current === 0) {
      console.log('✅ Face detected! Starting signal processing...');
      console.log('📊 Landmark count:', results.multiFaceLandmarks[0].length);
    }

    if (frameCountRef.current % 30 === 0) {
      console.log('📸 Processing frame', frameCountRef.current);
    }

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const landmarks = results.multiFaceLandmarks[0];

    // Draw video frame
    drawFrame(results.image, landmarks);

    // Extract ROIs and process signal
    const rois = extractROIs(results.image, landmarks, canvas);

    if (rois) {
      // Add to rolling buffer (keep last 300 frames = ~10 seconds at 30fps)
      const maxBufferSize = 300;
      ['forehead', 'leftCheek', 'rightCheek'].forEach(region => {
        rgbBufferRef.current[region].push(rois[region]);
        if (rgbBufferRef.current[region].length > maxBufferSize) {
          rgbBufferRef.current[region].shift();
        }
      });

      frameCountRef.current++;

      // Process signal every 10 frames (for performance)
      if (frameCountRef.current % 10 === 0 && rgbBufferRef.current.forehead.length >= 90) {
        processSignal();
      }
    }
  };

  // Process rPPG signal
  const processSignal = () => {
    const signalData = processRPPGSignal(rgbBufferRef.current);
    const confidence = calculateConfidence(signalData);

    // Update trust history
    trustHistoryRef.current.push({
      timestamp: Date.now(),
      confidence: confidence.overall
    });

    // Keep last 60 seconds of history
    const sixtySecondsAgo = Date.now() - 60000;
    trustHistoryRef.current = trustHistoryRef.current.filter(
      entry => entry.timestamp > sixtySecondsAgo
    );

    // Determine status
    let status = 'UNCERTAIN';
    if (confidence.signalQuality < 0.4) {
      status = 'UNCERTAIN';
    } else if (confidence.overall >= 0.65) {
      status = 'VERIFIED';
    } else if (confidence.overall < 0.45) {
      status = 'SUSPICIOUS';
    }

    onVerificationUpdate({
      status,
      confidence: confidence.overall,
      signalQuality: confidence.signalQuality,
      heartRate: signalData.heartRate,
      roiConsistency: confidence.roiConsistency,
      trustHistory: [...trustHistoryRef.current]
    });
  };

  // Draw video frame and landmarks
  const drawFrame = (image, landmarks = null) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');

    // Set canvas dimensions to match image
    if (canvas.width !== image.width || canvas.height !== image.height) {
      canvas.width = image.width;
      canvas.height = image.height;
    }

    ctx.save();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);

    if (landmarks) {
      // Draw ROI boxes
      drawROIBox(ctx, landmarks, 'forehead', '#6366f1');
      drawROIBox(ctx, landmarks, 'leftCheek', '#8b5cf6');
      drawROIBox(ctx, landmarks, 'rightCheek', '#a855f7');
    }

    ctx.restore();
  };

  // Draw ROI bounding box
  const drawROIBox = (ctx, landmarks, region, color) => {
    const indices = getROIIndices(region);
    const points = indices.map(i => ({
      x: landmarks[i].x * ctx.canvas.width,
      y: landmarks[i].y * ctx.canvas.height
    }));

    const minX = Math.min(...points.map(p => p.x));
    const maxX = Math.max(...points.map(p => p.x));
    const minY = Math.min(...points.map(p => p.y));
    const maxY = Math.max(...points.map(p => p.y));

    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.strokeRect(minX, minY, maxX - minX, maxY - minY);

    ctx.fillStyle = color;
    ctx.font = '12px monospace';
    ctx.fillText(region, minX, minY - 5);
  };

  // Get MediaPipe landmark indices for each ROI
  const getROIIndices = (region) => {
    switch (region) {
      case 'forehead':
        return [10, 67, 109, 338, 297]; // Upper forehead region
      case 'leftCheek':
        return [266, 426, 436, 416, 376]; // Left cheek
      case 'rightCheek':
        return [36, 206, 216, 192, 147]; // Right cheek
      default:
        return [];
    }
  };

  return (
    <div className="video-capture">
      <div className="video-container">
        <video
          ref={videoRef}
          className="video-element"
          playsInline
          muted
          autoPlay
        />
        <canvas ref={canvasRef} className="canvas-overlay" />

        {!isActive && (
          <div className="video-placeholder">
            <div className="placeholder-icon">📹</div>
            <p>{status}</p>
          </div>
        )}

        {isActive && !faceMesh && (
          <div className="loading-overlay">
            <div className="loading-spinner"></div>
            <p>Loading face detection...</p>
          </div>
        )}
      </div>

      <div className="controls">
        {!isActive ? (
          <button
            onClick={startCamera}
            className="btn-primary"
            disabled={!faceMesh || status === 'Error'}
          >
            {faceMesh ? 'Start Verification' : 'Loading...'}
          </button>
        ) : (
          <button onClick={stopCamera} className="btn-secondary">
            Stop
          </button>
        )}
      </div>

      {status && status !== 'Ready' && status !== 'Camera active' && !error && (
        <div className="status-message">
          <span>ℹ️</span>
          <p>{status}</p>
        </div>
      )}

      {error && (
        <div className="error-message">
          <span>⚠️</span>
          <p>{error}</p>
        </div>
      )}
    </div>
  );
};

export default VideoCapture;
